<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pageTitle='Movimentações de estoque';$pdo=db();$st=$pdo->query('SELECT m.*,p.nome produto_nome,u.nome usuario_nome FROM movimentacoes_estoque m JOIN produtos p ON p.id=m.produto_id LEFT JOIN usuarios u ON u.id=m.usuario_id ORDER BY m.id DESC LIMIT 300');$rows=$st->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Movimentações de estoque</h1><a class="btn secondary" href="index.php">Voltar</a></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Quantidade</th><th>Antes</th><th>Depois</th><th>Origem</th><th>Usuário</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=datetime_br($r['data_hora'])?></td><td><?=e($r['produto_nome'])?></td><td><?=e($r['tipo'])?></td><td><?=e($r['quantidade'])?></td><td><?=e($r['estoque_anterior'])?></td><td><?=e($r['estoque_posterior'])?></td><td><?=e($r['origem'])?></td><td><?=e($r['usuario_nome'])?></td></tr><?php endforeach; ?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
